  @const tuning = {}  @ 12
  @const HEIGHT_TOL = 1e-9  @ 382
  @const RATIO_CAP = 1 << 40  @ 477
  @const OCTAVE = 1200  @ 550
  @const REACH_TOL = 1e-9  @ 553
  @const FENCE = 1e-4  @ 557
  @const weights = {}  @ 732
  @const MIDI_NAMES = { 'C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', '...  @ 891

# Private functions
  -- Temperament presets
  @fn computeOctaveStep(stepNames, n)  @ 18-24
      -- octaveStep: first step whose label reads as the next octave's C. Scans from
      -- the end for the last non-C name; nameless scale → bump at period (n+1).
  @fn octaveLabel(o)  @ 28-30
      -- A negative octave renders as its magnitude, for the caller to tint — the
      -- sign costs no column. See docs/tuning.md § Display.
  @fn octaveFieldWidth(temper)  @ 34-39
      -- octaveFieldWidth: char width of the octave field, sized on the octave
      -- numbers at both ends of the range the root opens. See docs/tuning.md § Display.
  @fn computeRootCents(temper)  @ 43-46
      -- rootCents: where the scale's unison sits in sound, given the root's four
      -- authored fields. See docs/tuning.md § The root.
  @fn computeCellWidth(temper)  @ 49-58
      -- cellWidth: widest step label + the octave field; see docs/tuning.md § Display.
  @fn restateOnUnison(temper)  @ 102-106
      -- The root's step is gone: restate it on the unison, at the rootCents standing before the
      -- edit — the same tuning, written at the one step every scale keeps.
  @fn edo(n, names)  @ 140-149
  -- Scala import
  -- Generators
  @fn gcd(a, b)  @ 307
  @fn combinations(n, k)  @ 310-318
      -- Every k-subset of 1..n as a list of 1-based index lists.
  @fn primeFactorsBelow(n, limit)  @ 349-359
      -- Check if every prime factor of the odd `n` is at or below `limit`.
  @fn echelon(rows, width)  @ 387-409
      -- Integer row echelon over the prime columns, by gcd elimination: swap-and-subtract leaves
      -- the rows spanning the lattice they started from, so the nonzero ones are a basis of it.
      @contract  reduces `rows` in place; returns the rank and each row's pivot column  @ 386
  @fn reduceCents(c, period)  @ 464-466
      -- Reduce a cents value into [0, period).
  @fn asRatio(token)  @ 468-473
  @fn stackRatio(gn, gd, pn, pd, k)  @ 478-489
  @fn stepSpectrum(g, p, n)  @ 493-507
      -- Adjacent step sizes (incl. the wrap step) of an n-note chain of `g`
      -- reduced into `p`: {cents, count} per distinct size, large first.
  -- Coordinate conversions
  @fn stepAtCents(temper, cents)  @ 562-580
      -- The step nearest a point of the absolute cents line, and the period it falls in.
  @fn stepCents(temper, step, octave)  @ 591-596
      -- The absolute cents a step stands at, unclamped: a step past either end of MIDI range
      -- still has a place on the line, and the size of a move is measured before the clamp.
  @fn placeCents(cents)  @ 600-611
      -- A point of the cents line as MIDI. Overflow either end folds into the detune rather
      -- than being dropped, which is how a caller reads a move it has to refuse.
  @fn isOctaves(cents)  @ 657-660
      -- A whole number of 2/1 octaves, whatever the notation repeats at: the pitch class is
      -- what a solve tuned, so a move by one leaves a note's tuning standing.
  -- Targets
  @fn addOddFactors(n, coords, sign)  @ 688-699
      -- The odd primes of `n` accumulated into `coords` at `sign`. Twos are divided
      -- out first; whatever survives trial division past sqrt(n) is itself a prime.
  @fn weight(prime)  @ 733-737
  @fn coordKey(coords)  @ 771-780
      -- Coords fix a ratio up to the octave, so they identify a move outright: same coords,
      -- same reduced cents. Sorted, so a temper's two spellings of one move key alike.

# Public API (tuning.*)
  @api tuning.scalaPitch(token)  @ 61-79
      @contract  token → cents or nil: n/d, int, '.'=cents, n\m, n\m<equave> step (equave dflt 2/1).  @ 60
  @api tuning.derive(temper)  @ 82-98
      @contract  pitches→cents, periodPitch→period; stamps root/octave/cell fields. Pure; returns temper.  @ 81
  @api tuning.sortSteps(temper)  @ 109-122
      @contract  sort (pitches, stepNames) ascending by compiled cents, rootStep riding with its step  @ 108
  @api tuning.removeStep(temper, i)  @ 125-131
      @contract  drop step i, the root following the step it names; a root on i restates on the unison  @ 124
  @api tuning.unrooted(temper)  @ 134-138
      @contract  copy with the four root fields dropped and stamps refreshed at the default root  @ 133
  @api tuning.parseScalaPitches(text)  @ 177-184
      -- Lenient: every non-blank, non-'!' line is a pitch token. Drives paste + the
      -- import Create button (which re-parses the box after any manual edits).
  @api tuning.parseScalaFile(text)  @ 188-202
      -- Strict .scl: drop '!' comment lines, then [description, count, pitch x count].
      -- Returns pitch tokens + description (suggested name) for the Scala load path.
  @api tuning.scalaToTemper(pitchLines, name)  @ 206-224
      -- Bridge Scala's convention (unison implicit, period last) to Continuum's
      -- (step 1 = 1/1, period separate): prepend unison, split off final as period.
  @api tuning.edoDegrees(spec, mode)  @ 230-247
      -- Equal-division subset spec -> ascending degrees; largest is the period.
      -- 'relative': cumulative step counts. 'absolute': sorted+deduped. nil on bad token.
  @api tuning.degreesToSpec(degrees, mode)  @ 251-256
      -- Inverse of edoDegrees: render a degree list back as a spec string in `mode`.
      -- Lets a mode switch convert the in-flight pattern rather than reset it.
  @api tuning.genEqual(degrees, interval)  @ 260-266
      -- N-equal-divisions of `interval` subset to `degrees`; tokens are intensional
      -- (d\D<equave>, suffix omitted for octave). Base 0 implicit; last degree = period.
  @api tuning.genHarmonics(lo, hi)  @ 270-274
      -- Harmonic-series segment lo..hi: ratios m/lo rooted on the low harmonic, the
      -- top (hi/lo) the period.
  @api tuning.genSubharmonics(lo, hi)  @ 277-281
      -- Subharmonic (utonal) segment lo..hi: ratios hi/m ascending, top the period.
  @api tuning.parseChord(spec)  @ 285-294
      -- Colon/space-separated extended ratio (e.g. '4:5:6:7') -> positive integers,
      -- at least two. nil + message otherwise.
  @api tuning.genChord(members, invert)  @ 298-305
      -- Enumerate a chord as a scale rooted on its first note. otonal: ci/c1.
      -- inverted (utonal): ck/c(k+1-i). The last member is the period either way.
  @api tuning.genCPS(factors, k, equave)  @ 322-346
      -- Combination product set: every k-subset's product, rooted on the smallest
      -- product (so 1/1 is always present) and reduced into the equave; ascending.
  @api tuning.genDiamond(oddLimit, primeLimit)  @ 363-378
      -- N-odd-limit tonality diamond: coprime odd pairs to `oddLimit`, reduced into the
      -- octave; `primeLimit` filters larger primes. See design/adaptive-tuning.md § The diamond.
  @api tuning.genTenney(generators, bound)  @ 415-461
      -- The generating intervals span a lattice over the odd primes; the bound cuts a ball from it,
      -- enumerated over an echelon basis of the generators. See design/adaptive-tuning.md § The Tenney ball.
      @contract  ratio tokens + a bound token → every composition within the bound, ascending  @ 413
      @contract  assumes ratios throughout, the caller having validated them  @ 414
  @api tuning.genRank2(generator, period, size, up)  @ 511-530
      -- Rank-2 scale: stack the generator `up` above and `size-1-up` below 1/1,
      -- reduce into period, sort. up = mode. Exact ratios if inputs rational, else cents.
  @api tuning.mosInfo(generator, period, n)  @ 533-537
      @contract  {isMos, large, small} for an n-note chain; large/small are L/s step counts when isMos  @ 532
  @api tuning.nextMosSize(generator, period, fromN, dir)  @ 540-548
      @contract  next MOS size (two step sizes) from fromN, stepping dir (+/-1); nil past the cap  @ 539
  @api tuning.midiToStep(temper, midi, detune)  @ 585-587
      @contract  detune optional (defaults 0)  @ 582
      @contract  snaps to nearest scale point, the period boundary rounding up to next octave's step 1  @ 583
      @contract  returned octave is period-index + temper.octaveBase (at the default root, C-1 → -1)  @ 584
  @api tuning.stepToMidi(temper, step, octave)  @ 615-617
      @contract  wraps out-of-range step by adjusting octave  @ 613
      @contract  clamps midi to 0..127 by folding overflow into detune (never silently drops)  @ 614
  @api tuning.snap(temper, midi, detune)  @ 619-621
  @api tuning.noteStep(notation, note)  @ 627-630
      -- Where a note was written, which is not always where it sounds -- see
      -- design/sounding-anchor.md § What the note remembers.
      @contract  notation, note → the step and octave the note was written on  @ 625
      @contract  the step note.intentCents stands on, or the one its pitch snaps to where it carries none  @ 626
  @api tuning.stepClass(temper, note)  @ 635-638
      -- The step a note is written on, taken modulo the octave the score quotients
      -- out. See design/adaptive-tuning.md § The model.
      @contract  the note's written seat reduced into the octave; an octave apart answers alike  @ 634
  @api tuning.stepWindow(temper, step)  @ 641-647
      @contract  half-gaps in cents to steps below/above `step`; both positive, wraps the period  @ 640
  @api tuning.transposeStep(temper, midi, detune, n)  @ 650-653
      @contract  moves by n scale steps under temper, carrying the octave; n may be negative  @ 649
  @api tuning.transposeNote(temper, note, n)  @ 667-675
      -- A transpose steps from where a note was written rather than from where it sounds.
      -- see design/sounding-anchor.md § What the note remembers
      @contract  temper, note, n steps → the pitch, detune and intent cents of the note moved n steps  @ 664
      @contract  a move of whole 2/1 octaves keeps the note's drift and carries its intent  @ 665
      @contract  any other move seats the note on the step it lands on and spends the intent  @ 666
  @api tuning.stepsBetween(temper, aMidi, aDetune, bMidi, bDetune)  @ 678-682
      @contract  signed count of whole temper steps from note a to note b, each snapped to nearest step  @ 677
  @api tuning.coords(token)  @ 704-714
      -- Numerator and denominator are factorised apart and their exponents subtracted,
      -- so 6/4 and 3/2 read alike and a prime on both sides cancels rather than sitting at zero.
      @contract  ratio token -> {[oddPrime]=exponent}, prime 2 divided out; nil for cents or n\m  @ 703
  @api tuning.ratio(coords)  @ 719-729
      -- The odd primes multiplied back out, then doubled or halved into the octave; coords carry no
      -- power of two, so this inverts tuning.coords up to that reduction.
      @contract  {[oddPrime]=exponent} → the octave-reduced ratio token they name  @ 718
  @api tuning.height(coords)  @ 742-748
      -- Read off the coords, so an unreduced token costs the interval it sounds, not its terms.
      -- See docs/tuning.md § A temper read as moves.
      @contract  coords → the octave-free Tenney height of the ratio they name: Σ |exponent| × log₂ p  @ 741
  @api tuning.cents(coords)  @ 753-759
      -- Read signed where the height reads absolute, so a descent comes out negative;
      -- prime 2 is divided out of coords, so the figure is exact only up to the octave.
      @contract  coords → Σ exponent × 1200 log₂ p: the cents of the ratio they name, octave-free  @ 752
  @api tuning.isTarget(temper)  @ 762-767
      @contract  true when every pitch of `temper` is a ratio, so its points carry coords to score  @ 761
  @api tuning.moves(temper)  @ 788-816
      -- A move set read as intervals from its unison, per docs/tuning.md § A temper read as
      -- moves; an inversion carries the same height, so it sorts beside the move it inverts.
  @api tuning.gapTo(seat, cents)  @ 821-823
      -- The gap from a seat to a point of the octave-reduced line, signed and reduced so a
      -- point below the seat reads as a descent, not an ascent; sonority's springs read it too.
      @contract  cents - seat, reduced to the nearest octave  @ 820
  @api tuning.seatWindow(notation, note)  @ 829-834
      -- A note's own step: where it seats, and how far its window reaches either side.
      -- The shortlist, the reach and the root are all measured off it.
      @contract  notation, note → the cents of the note's own step, and its half-gaps below and above  @ 827
      @contract  the halves stop a hair inside the edge, where the note's own step stops reading back  @ 828
  @api tuning.shortlist(notation, target, keyStep, note, widen)  @ 841-875
      -- The only place the notation and the target meet. See design/adaptive-tuning.md
      -- § What the solver takes for why the line is reduced into the octave.
      @contract  candidates {cents, coords, strain} for the target's points inside the note's step window  @ 838
      @contract  strain is the point's gap over the window half it lies in; nearest first  @ 839
      @contract  widen: where the window holds nothing, the nearest points instead, at strain past 1  @ 840
  @api tuning.seat(notation, note, cents)  @ 880-885
      -- The shortlist's fold in reverse: a point the strand took, in the register of one
      -- of the notes that writes it, the note's own step seat being what the window was measured off.
      @contract  (pitch, detune) for `cents` placed in the octave nearest the note's seat  @ 879
  -- Display
  @api tuning.midiName(pitch)  @ 894-896
      @contract  MIDI number → untempered twelve-name spelling (0 → 'C-1', 60 → 'C4')  @ 893
  @api tuning.stepToParts(temper, step, octave)  @ 899-904
      @contract  (note, octaveLabel=|octave|, negative); name or degree+'-'; octave+1 at octaveStep  @ 898

